 $('modalMessage').textContent='';const actionsBox=$('modalForm').querySelector('.modal-actions');actionsBox.style.display='flex';actionsBox.innerHTML=`<button type="button" class="btn outline" id="orderCloseBtn">Close</button><button type="button" class="btn secondary" id="modalPrintReceipt">Print receipt</button><button type="button" class="btn primary" id="showPaymentQrBtn">Show QR for Pay</button>`;
 $('orderCloseBtn').onclick=()=>{$('modal').close();actionsBox.innerHTML='<button type="button" class="btn outline" id="modalCancel">Cancel</button><button class="btn primary" type="submit">Save</button>';const cancel=$('modalCancel');if(cancel)cancel.onclick=()=>$('modal').close();};
