function localDateKey(date=new Date()){
 const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');
 return `${y}-${m}-${d}`;
}
function reportPeriodBounds(range,startValue='',endValue=''){
 const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate());let start=null,end=null;
 if(range==='today'){start=today;end=new Date(today.getTime()+86400000-1)}
 else if(range==='yesterday'){start=new Date(today.getTime()-86400000);end=new Date(today.getTime()-1)}
 else if(range==='this-week'){const day=(today.getDay()+6)%7;start=new Date(today.getFullYear(),today.getMonth(),today.getDate()-day);end=new Date(start.getTime()+7*86400000-1)}
 else if(range==='last-week'){const day=(today.getDay()+6)%7;start=new Date(today.getFullYear(),today.getMonth(),today.getDate()-day-7);end=new Date(start.getTime()+7*86400000-1)}
 else if(range==='this-month'){start=new Date(now.getFullYear(),now.getMonth(),1);end=new Date(new Date(now.getFullYear(),now.getMonth()+1,1).getTime()-1)}
 else if(range==='last-month'){start=new Date(now.getFullYear(),now.getMonth()-1,1);end=new Date(new Date(now.getFullYear(),now.getMonth(),1).getTime()-1)}
 else if(range==='custom-date'&&startValue){start=new Date(startValue+'T00:00:00');end=new Date(start.getTime()+86400000-1)}
 else if(range==='custom-range'&&startValue&&endValue){start=new Date(startValue+'T00:00:00');end=new Date(endValue+'T23:59:59.999')}
 return {start,end};
}
function renderReports(){
 const completedOrders=orders.filter(o=>o.status==='completed'),totalRevenue=completedOrders.reduce((sum,o)=>sum+Number(o.total_amount||0),0),completed=completedOrders.length;
 const todayKey=localDateKey(),todayCompleted=completedOrders.filter(o=>localDateKey(new Date(o.created_at))===todayKey),todayRevenue=todayCompleted.reduce((sum,o)=>sum+Number(o.total_amount||0),0);
 const todayClose=dailyClosings.find(c=>String(c.business_date).slice(0,10)===todayKey),counts=categories.map(c=>({name:c.name,count:items.filter(i=>i.category_id===c.id).length})),max=Math.max(1,...counts.map(c=>c.count));
 const dates=`<div class="report-date-controls"><label>Income period<select id="reportRange"><option value="today" ${reportRange==='today'?'selected':''}>Today</option><option value="yesterday" ${reportRange==='yesterday'?'selected':''}>Yesterday</option><option value="this-week" ${reportRange==='this-week'?'selected':''}>This week</option><option value="last-week" ${reportRange==='last-week'?'selected':''}>Last week</option><option value="this-month" ${reportRange==='this-month'?'selected':''}>This month</option><option value="last-month" ${reportRange==='last-month'?'selected':''}>Last month</option><option value="custom-date" ${reportRange==='custom-date'?'selected':''}>Specific date</option><option value="custom-range" ${reportRange==='custom-range'?'selected':''}>Custom date range</option><option value="all-time" ${reportRange==='all-time'?'selected':''}>All time</option></select></label><label id="reportStartWrap" class="${['custom-date','custom-range'].includes(reportRange)?'':'hidden'}">${reportRange==='custom-date'?'Choose date':'Start date'}<input type="date" id="reportStartDate"></label><label id="reportEndWrap" class="${reportRange==='custom-range'?'':'hidden'}">End date<input type="date" id="reportEndDate"></label></div>`;
 $('pageContent').innerHTML=heading('Reports & summary','Track income by day, week, month or a custom date. Revenue includes completed orders only.')+
 `<div class="panel report-income-panel"><div class="panel-head"><div><h3>Income report</h3><p class="muted">Choose a period to see completed-order income.</p></div></div>${dates}<div id="filteredIncomeStats" class="stats"></div><div id="filteredIncomeMeta" class="order-meta"></div></div>
 <div class="stats">${stat('All-time completed revenue',money(totalRevenue),'Nu','Completed orders only')}${stat('Completed orders',completed,'✓','Revenue-eligible orders')}${stat('Total orders',orders.length,'☷','All loaded orders')}${stat('Menu items',items.length,'🍽',`${categories.length} categories`)}</div>
 <div class="panel" style="margin-bottom:18px"><div class="panel-head"><div><h3>Daily closing · ${todayKey}</h3><p class="muted">Manual closing only. This action records today's completed-order totals and does not close automatically.</p></div>${todayClose?'<span class="status">Closed</span>':'<span class="status off">Open</span>'}</div><div class="stats">${stat("Today's completed orders",todayCompleted.length,'✓','Completed status only')}${stat("Today's revenue",money(todayRevenue),'Nu','Completed orders only')}</div>${todayClose?`<p class="qr-note">Closed at ${dateText(todayClose.closed_at)} · ${Number(todayClose.completed_orders||0)} completed orders · ${money(todayClose.revenue)} recorded revenue.</p>`:`<button class="btn primary" id="manualDailyClose">Close day manually</button>`}<div id="dailyCloseMessage" class="message" role="status"></div></div>
 <div class="report-grid"><div class="panel"><div class="panel-head"><h3>Items by category</h3></div>${counts.length?counts.map(c=>`<div class="bar-row"><span>${esc(c.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${c.count/max*100}%"></div></div><b>${c.count}</b></div>`).join(''):'<div class="empty">Add categories to see this report.</div>'}</div><div class="panel"><div class="panel-head"><h3>Order status breakdown</h3></div>${['pending','confirmed','preparing','ready','completed','cancelled'].map(status=>`<div class="bar-row"><span>${status}</span><div class="bar-track"><div class="bar-fill" style="width:${orders.length?orders.filter(o=>o.status===status).length/orders.length*100:0}%"></div></div><b>${orders.filter(o=>o.status===status).length}</b></div>`).join('')}<button class="btn outline" id="exportOrders">Export orders CSV</button></div></div>`;
 const startInput=$('reportStartDate'),endInput=$('reportEndDate');if(startInput)startInput.value=window.reportStartDate||todayKey;if(endInput)endInput.value=window.reportEndDate||todayKey;
 const updateIncome=()=>{
  const range=$('reportRange').value;reportRange=range;const sv=$('reportStartDate')?.value||todayKey,ev=$('reportEndDate')?.value||sv;
  $('reportStartWrap').classList.toggle('hidden',!['custom-date','custom-range'].includes(range));$('reportEndWrap').classList.toggle('hidden',range!=='custom-range');
  const bounds=reportPeriodBounds(range,sv,ev),filtered=completedOrders.filter(o=>{const d=new Date(o.created_at);return range==='all-time'||((!bounds.start||d>=bounds.start)&&(!bounds.end||d<=bounds.end));});
  const amount=filtered.reduce((sum,o)=>sum+Number(o.total_amount||0),0);$('filteredIncomeStats').innerHTML=stat('Income',money(amount),'Nu','Completed orders only')+stat('Completed orders',filtered.length,'✓','Within selected period');
  $('filteredIncomeMeta').textContent=range==='all-time'?'Showing all completed orders.':`Showing ${bounds.start?localDateKey(bounds.start):'—'} to ${bounds.end?localDateKey(bounds.end):'—'} · ${filtered.length} completed order${filtered.length===1?'':'s'}`;
 };
 $('reportRange').onchange=()=>{const r=$('reportRange').value;reportRange=r;renderReports()};if(startInput)startInput.onchange=()=>{window.reportStartDate=startInput.value;updateIncome()};if(endInput)endInput.onchange=()=>{window.reportEndDate=endInput.value;updateIncome()};updateIncome();
 const closeButton=$('manualDailyClose');if(closeButton)closeButton.onclick=async()=>{if(!confirm(`Manually close ${todayKey}? This records ${todayCompleted.length} completed orders and ${money(todayRevenue)} revenue.`))return;closeButton.disabled=true;closeButton.textContent='Closing…';const payload={business_date:todayKey,closed_at:new Date().toISOString(),completed_orders:todayCompleted.length,revenue:Number(todayRevenue.toFixed(2))};const {data,error}=await db.from('daily_closings').upsert(payload,{onConflict:'business_date'}).select().single();if(error){setMessage('dailyCloseMessage',`Could not close day: ${error.message}`);closeButton.disabled=false;closeButton.textContent='Close day manually';return}dailyClosings=[data,...dailyClosings.filter(c=>String(c.business_date).slice(0,10)!==todayKey)];toast('Daily closing recorded');renderReports()};
 $('exportOrders').onclick=exportOrders;
}

function wireActions(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions(b.dataset.action,b.dataset.id))}
function actions(a,id){if(a.startsWith('goto-'))return go(a.slice(5));if(a==='add-user')return openForm('user');if(a==='edit-user')return openForm('user',staffUsers.find(x=>x.id===id));if(a==='toggle-user'){const u=staffUsers.find(x=>x.id===id);return saveRecord('admin_staff',{is_active:!u.is_active},id)}if(a==='delete-user')return deleteRecord('user',id);if(a==='add-category')return openForm('category');if(a==='edit-category')return openForm('category',categories.find(x=>x.id===id));if(a==='add-item')return openForm('item');if(a==='edit-item')return openForm('item',items.find(x=>x.id===id));if(a==='add-room')return openForm('room');if(a==='edit-room')return openForm('room',rooms.find(x=>x.id===id));if(a==='view-order')return showOrder(id);if(a==='track-order')return showOrder(id);if(a==='print-order-receipt')return printOrderReceipt(id);if(a==='copy-qr'){const r=rooms.find(x=>x.id===id);navigator.clipboard?.writeText(r.qr_code).then(()=>toast('QR code value copied'));return}if(a==='copy-qr-link'){const r=rooms.find(x=>x.id===id);const url=location.href.split('?')[0].replace(/index\.html?$/i,'').replace(/\/$/,'')+'/customer.html?qr='+encodeURIComponent(r.qr_code);navigator.clipboard?.writeText(url).then(()=>toast('Customer QR link copied'));return}if(a==='print-qr'){const r=rooms.find(x=>x.id===id);const url=location.href.split('?')[0].replace(/index\.html?$/i,'').replace(/\/$/,'')+'/customer.html?qr='+encodeURIComponent(r.qr_code);const img='https://api.qrserver.com/v1/create-qr-code/?size=320x320&data='+encodeURIComponent(url);const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print the QR code');return}w.document.write('<html><head><title>QR - '+esc(r.name)+'</title><style>body{font-family:Arial;text-align:center;padding:30px}img{width:320px;height:320px;display:block;margin:20px auto}p{overflow-wrap:anywhere}</style></head><body><h1>'+esc(r.name)+'</h1><img src=\"'+img+'\" alt=\"QR code\"><p>Scan to order</p><p>'+esc(url)+'</p><script>window.onload=()=>setTimeout(()=>window.print(),500)<\/script></body></html>');w.document.close();return}if(a==='toggle-item'){const i=items.find(x=>x.id===id);return saveRecord('food_items',{is_available:!i.is_available},id)}if(a.startsWith('delete-'))return deleteRecord(a.slice(7),id)}
function field(name,label,type='text',value='',extra=''){return `<label class="field">${label}${type==='select'?`<select name="${name}" ${extra}>${value}</select>`:type==='textarea'?`<textarea name="${name}" rows="3" ${extra}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</label>`}
function openForm(type,record=null){const actionsBox=$('modalForm').querySelector('.modal-actions');actionsBox.style.display='flex';actionsBox.innerHTML='<button type="button" class="btn outline" id="modalCancel">Cancel</button><button class="btn primary" type="submit">Save</button>';const cancel=$('modalCancel');if(cancel)cancel.onclick=()=>$('modal').close();const edit=!!record;$('modalTitle').textContent=(edit?'Edit ':'Add ')+({category:'category',item:'food item',room:'room / table',user:'staff profile'}[type]);$('modalMessage').textContent='';let html='';
if(type==='user')html=field('username','Username','text',record?.username||'','required')+field('email','Email address','email',record?.email||'','required')+`<label class="field">Role<select name="role"><option ${record?.role==='staff'?'selected':''}>staff</option><option ${record?.role==='manager'?'selected':''}>manager</option></select></label>`+`<label class="field">Status<select name="is_active"><option value="true" ${record?.is_active!==false?'selected':''}>Active</option><option value="false" ${record?.is_active===false?'selected':''}>Inactive</option></select></label>`+`<p class="qr-note">Create the login in Supabase Authentication → Users.</p>`;if(type==='category')html=field('name','Category name','text',record?.name||'','required')+field('description','Description','textarea',record?.description||'')+`<label class="field">Status<select name="is_active"><option value="true" ${record?.is_active!==false?'selected':''}>Active</option><option value="false" ${record?.is_active===false?'selected':''}>Inactive</option></select></label>`;
if(type==='item')html=field('name','Food item name','text',record?.name||'','required')+field('description','Description','textarea',record?.description||'')+field('category_id','Category','select',`<option value="">Select category</option>${categories.map(c=>`<option value="${c.id}" ${record?.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}`,'required')+field('price','Price (Nu.)','number',record?.price??'','min="0" step="0.01" required')+`<label class="field">Food image (optional)<input name="image_file" type="file" accept="image/*"><small class="muted">${record?.image_url?'Current image is saved. Choose a file to replace it.':'Upload an image directly.'}</small></label>`+`<label class="field">Availability<select name="is_available"><option value="true" ${record?.is_available!==false?'selected':''}>Available</option><option value="false" ${record?.is_available===false?'selected':''}>Unavailable</option></select></label>`;
if(type==='room')html=field('name','Room / table name','text',record?.name||'','required')+`<label class="field">Location type<select name="location_type"><option ${record?.location_type==='room'?'selected':''}>room</option><option ${record?.location_type==='table'?'selected':''}>table</option></select></label>`+field('capacity','Capacity','number',record?.capacity||'','min="1"')+field('description','Description','textarea',record?.description||'')+`<label class="field">Status<select name="is_active"><option value="true" ${record?.is_active!==false?'selected':''}>Active</option><option value="false" ${record?.is_active===false?'selected':''}>Inactive</option></select></label>`+`<p class="qr-note">A QR code is generated automatically on save.</p>`;
$('modalFields').innerHTML=html;$('modal').dataset.type=type;$('modal').dataset.id=record?.id||'';$('modal').showModal()}
$('modalClose').onclick=$('modalCancel').onclick=()=>$('modal').close();
$('modalForm').onsubmit=async e=>{e.preventDefault();const type=$('modal').dataset.type,id=$('modal').dataset.id,fd=new FormData(e.target),data=Object.fromEntries(fd.entries());if(type==='item'){const file=fd.get('image_file');delete data.image_file;if(file&&file.size){try{data.image_url=await uploadImage(file,'food-images')}catch(err){setMessage('modalMessage',err.message);return}}else if(id){const old=items.find(x=>x.id===id);if(old?.image_url)data.image_url=old.image_url}}if('is_active'in data)data.is_active=data.is_active==='true';if('is_available'in data)data.is_available=data.is_available==='true';if('price'in data)data.price=Number(data.price);if('capacity'in data)data.capacity=data.capacity?Number(data.capacity):null;if(type==='room'&&!id)data.qr_code='QB-'+crypto.randomUUID().replaceAll('-','').slice(0,10).toUpperCase();const table={category:'food_categories',item:'food_items',room:'dining_locations',user:'admin_staff'}[type];await saveRecord(table,data,id,true)}
async function saveRecord(table,data,id,closeModal=false){try{let q=id?db.from(table).update(data).eq('id',id):db.from(table).insert(data);const {error}=await q;if(error){if(closeModal)setMessage('modalMessage',error.message);else toast(error.message);return}if(closeModal)$('modal').close();toast(id?'Changes saved':'Added successfully');await loadAll()}catch(err){const msg='Could not reach Supabase: '+(err.message||'network error')+'. Check your internet connection and that your Supabase project is active.';if(closeModal)setMessage('modalMessage',msg);else toast(msg)}}
async function deleteRecord(type,id){const table={category:'food_categories',item:'food_items',room:'dining_locations',user:'admin_staff'}[type];if(!confirm('Delete this record? This cannot be undone.'))return;const {error}=await db.from(table).delete().eq('id',id);if(error)toast(error.message);else{toast('Deleted');await loadAll()}}
function exportOrders(){const rows=[['Order number','Customer','Room/Table','Date','Total amount','Status'],...orders.map(o=>[o.order_number||o.id,o.customer_name||'Guest',o.dining_locations?.name||'',o.created_at,o.total_amount,o.status])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='quickbite-orders.csv';a.click();URL.revokeObjectURL(a.href)}
function updateOrderBadges(){
 const pending=orders.filter(o=>['pending','confirmed','preparing'].includes(o.status)).length;
 $('orderBadge').textContent=pending;
 $('orderBadge').classList.toggle('hidden',pending===0);
 const live=$('liveOrderCount');if(live)live.textContent=String(newOrderCount);const top=$('topNotificationBadge');if(top){top.textContent=String(newOrderCount);top.classList.toggle('hidden',newOrderCount===0);}
}
function unlockOrderAudio(){
 try{const Ctx=window.AudioContext||window.webkitAudioContext;if(Ctx){audioContext=audioContext||new Ctx();if(audioContext.state==='suspended')audioContext.resume();}}catch(e){}
}
function playOrderChime(){
 try{
  const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return;
  audioContext=audioContext||new Ctx();if(audioContext.state==='suspended')audioContext.resume();
  const now=audioContext.currentTime;
  [660,880,1046].forEach((freq,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(0.0001,now+i*.13);gain.gain.exponentialRampToValueAtTime(.16,now+i*.13+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+i*.13+.32);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+i*.13);osc.stop(now+i*.13+.34);});
 }catch(e){}
}
function announceNewOrder(order){
 if(!order?.id||announcedOrderIds.has(order.id))return;
 announcedOrderIds.add(order.id);
 newOrderCount++;updateOrderBadges();
 const orderNo=order.order_number||String(order.id).slice(0,8),table=order.dining_locations?.name||'Restaurant';
 const lines=orderItems.filter(i=>i.order_id===order.id);
 const alert=document.createElement('div');alert.className='new-order-toast';
 alert.innerHTML=`<div class="new-order-toast-icon">🔔</div><div class="new-order-toast-copy"><strong>New order received!</strong><span>Order #${esc(orderNo)} · ${esc(table)}</span><small>${esc(order.customer_name||'Guest')} · ${money(order.total_amount)} · ${dateText(order.created_at)}</small><div class="new-order-toast-items">${lines.slice(0,4).map(i=>`${esc(i.item_name||i.food_items?.name||'Item')} × ${i.quantity}`).join('<br>')}${lines.length>4?`<br>+${lines.length-4} more items`:''}</div><button type="button" class="btn primary new-order-view">View order details</button></div><button type="button" class="new-order-dismiss" aria-label="Dismiss">×</button>`;
 document.body.appendChild(alert);
 alert.querySelector('.new-order-dismiss').onclick=()=>alert.remove();
 alert.querySelector('.new-order-view').onclick=()=>{alert.remove();go('orders');showOrder(order.id);newOrderCount=Math.max(0,newOrderCount-1);updateOrderBadges()};
 setTimeout(()=>alert.remove(),16000);
 if(orderSoundEnabled){playOrderChime();if('speechSynthesis'in window){try{const utterance=new SpeechSynthesisUtterance(`New order. Table ${table}. Total ${Number(order.total_amount||0)} ngultrum.`);utterance.rate=.95;window.speechSynthesis.speak(utterance);}catch(e){}}}
}
function startOrderWatcher(){
 if(orderWatcher){clearInterval(orderWatcher);orderWatcher=null;}
 if(!orderWatchStartedAt)orderWatchStartedAt=new Date().toISOString();seenLiveOrderIds.clear();newOrderCount=0;updateOrderBadges();
 const check=async()=>{
  if(!db||!orderWatchStartedAt||orderCheckInProgress)return;
  orderCheckInProgress=true;
  try{
  const {data,error}=await db.from('food_orders').select('*, dining_locations(name)').gt('created_at',orderWatchStartedAt).order('created_at',{ascending:true}).limit(200);
  if(error)return;
  const fresh=(data||[]).filter(o=>!seenLiveOrderIds.has(o.id)&&!announcedOrderIds.has(o.id));
  if(!fresh.length)return;
  fresh.forEach(o=>seenLiveOrderIds.add(o.id));
  const ids=fresh.map(o=>o.id);
  const [itemsResult]=await Promise.all([db.from('food_order_items').select('*, food_items(name)').in('order_id',ids)]);
  orders=[...fresh.reverse(),...orders.filter(o=>!ids.includes(o.id))].slice(0,500);
  orderItems=[...(itemsResult.data||[]),...orderItems.filter(i=>!ids.includes(i.order_id))];
  fresh.forEach(announceNewOrder);
  if(page==='orders')renderOrders();
  else if(page==='home')renderHome();
  updateOrderBadges();
  }catch(err){console.warn('Order notification check failed:',err)}finally{orderCheckInProgress=false}
 };
 orderWatcher=setInterval(check,7000);
}
init();

function renderUsers(){
 $('pageContent').innerHTML=heading('User management','Create and manage staff profiles and access status.','Add user','add-user')+
 `<div class="qr-note" style="margin-bottom:16px">Staff logins are created in Supabase Authentication. This page manages profile & status only.</div>
 <div class="table-wrap"><table class="data-table"><thead><tr><th>Username</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${staffUsers.map(u=>`<tr><td><b>${esc(u.username)}</b></td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${u.is_active?'<span class="status">Active</span>':'<span class="status off">Inactive</span>'}</td><td><div class="actions"><button class="small-btn" data-action="edit-user" data-id="${u.id}">Edit</button><button class="small-btn" data-action="toggle-user" data-id="${u.id}">${u.is_active?'Deactivate':'Activate'}</button><button class="small-btn danger" data-action="delete-user" data-id="${u.id}">Delete profile</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No staff profiles yet.</td></tr>'}</tbody></table></div>`;
 wireActions();
}
function renderSettings(){
 const x=settingsRecord||{};
 $('pageContent').innerHTML=heading('Restaurant settings','Set the restaurant identity shown throughout the system.')+
 `<div class="panel" style="max-width:720px"><form id="settingsForm">
 ${field('restaurant_name','Restaurant name','text',x.restaurant_name||'','required')}
 ${field('location','Restaurant location','text',x.location||'','required')}
 ${field('owner_name','Owner name','text',x.owner_name||'')}
 ${field('contact_email','Owner / contact email','email',x.contact_email||'')}
 ${field('contact_phone','Owner / contact phone','tel',x.contact_phone||'')}
 <label class="field">Owner photo (optional)<input id="ownerPhotoFile" name="owner_photo_file" type="file" accept="image/*"><small class="muted">${x.owner_photo_url?'Current owner photo is saved. Choose a file to replace it.':'Upload an owner photo.'}</small>${x.owner_photo_url?`<img src="${esc(x.owner_photo_url)}" alt="Current owner photo" style="max-width:140px;max-height:140px;object-fit:cover;border-radius:50%;border:1px solid var(--line);padding:4px">`:''}</label>
 <label class="field">Restaurant logo (optional)<input id="logoFile" name="logo_file" type="file" accept="image/*"><small class="muted">${x.logo_url?'Current logo is saved. Choose a file to replace it.':'Upload your logo directly.'}</small>${x.logo_url?`<img src="${esc(x.logo_url)}" alt="Current logo" style="max-width:140px;max-height:100px;object-fit:contain;border:1px solid var(--line);border-radius:10px;padding:8px">`:''}</label>
 <label class="field">Payment QR code<input id="paymentQrFile" name="payment_qr_file" type="file" accept="image/png,image/jpeg,image/webp"><small class="muted">Upload the QR image customers should scan to pay (maximum 5 MB). ${x.payment_qr_url?'Choose a new image to replace the current payment QR.':'No payment QR uploaded yet.'}</small>${x.payment_qr_url?`<img src="${esc(x.payment_qr_url)}" alt="Current payment QR code" style="max-width:190px;max-height:190px;object-fit:contain;border:1px solid var(--line);border-radius:10px;padding:8px;background:#fff">`:''}</label>
 <button class="btn primary" type="submit">Save settings</button><p id="settingsMessage" class="message"></p></form></div>`;
 $('settingsForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const data={restaurant_name:fd.get('restaurant_name'),location:fd.get('location'),owner_name:fd.get('owner_name'),contact_email:fd.get('contact_email'),contact_phone:fd.get('contact_phone')};const file=fd.get('logo_file');const ownerFile=fd.get('owner_photo_file');const qrFile=fd.get('payment_qr_file');try{if(file&&file.size){data.logo_url=await uploadImage(file,'restaurant-logos')}else if(settingsRecord?.logo_url)data.logo_url=settingsRecord.logo_url;if(ownerFile&&ownerFile.size){data.owner_photo_url=await uploadImage(ownerFile,'owner-photos')}else if(settingsRecord?.owner_photo_url)data.owner_photo_url=settingsRecord.owner_photo_url;if(qrFile&&qrFile.size){data.payment_qr_url=await uploadImage(qrFile,'payment-qr')}else if(settingsRecord?.payment_qr_url)data.payment_qr_url=settingsRecord.payment_qr_url;const q=settingsRecord?db.from('restaurant_settings').update({...data,updated_at:new Date().toISOString()}).eq('id',settingsRecord.id):db.from('restaurant_settings').insert(data);const {error}=await q;if(error){setMessage('settingsMessage',error.message);return}toast('Restaurant settings saved');await loadAll()}catch(err){setMessage('settingsMessage','Could not reach Supabase: '+(err.message||'network error')+'. Check your internet connection and that your Supabase project is active.')}};
}
